const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const descriptions={'Dumaguete–Valencia':'A city-and-countryside escape combining the charm of Dumaguete with the lush surroundings of Valencia.','Manjuyod':'A coastal getaway to the Manjuyod sandbar. Sandbar visibility and sea activities depend on tides and weather.','Apo Island':'An island escape for marine-life lovers. Ask our team about snorkeling options and the arrangements for your visit.','Siquijor':'Discover Siquijor at your own pace, with beach and inland sightseeing options to discuss with our team.'};
const dialog=document.querySelector('#package-dialog');
document.querySelectorAll('[data-tour]').forEach(button=>button.addEventListener('click',()=>{const tour=button.dataset.tour;document.querySelector('#package-title').textContent=tour;document.querySelector('#package-description').textContent=descriptions[tour];document.querySelector('#package-email').href='mailto:lupadta.traveltours@gmail.com?subject='+encodeURIComponent(tour+' package inquiry')+'&body='+encodeURIComponent('Hello LUPAD-Ta! I would like to inquire about your '+tour+' package.\n\nTravel dates: \nNumber of guests: \n\nPlease share your current rates and inclusions.');dialog.showModal()}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
